import React, { useState, useEffect, useRef } from 'react';
import { 
  MessageCircle, 
  Send, 
  Mic, 
  Brain, 
  X, 
  Minimize2,
  Maximize2,
  Volume2,
  Square,
  Zap,
  CheckCircle,
  AlertCircle,
  Loader,
  Settings,
  RefreshCw,
  Info
} from 'lucide-react';

const ChatAssistant = ({ data, isOpen, setIsOpen, onTabChange }) => {
  const [messages, setMessages] = useState([
    {
      id: 1,
      type: 'ai',
      content: "Hello! I'm your AI Assistant for Modern International School ERP. I can help you with student records, teacher management, finances, inventory, and analytics. What would you like to know?",
      timestamp: new Date().toISOString()
    }
  ]);
  const [inputMessage, setInputMessage] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [currentTranscript, setCurrentTranscript] = useState('');
  const [typingIndicator, setTypingIndicator] = useState('');
  const [connectionStatus, setConnectionStatus] = useState('disconnected');
  const [debugInfo, setDebugInfo] = useState('');
  const [showDebug, setShowDebug] = useState(false);
  const [modelInfo, setModelInfo] = useState(null);

  const messagesEndRef = useRef(null);
  const recognitionRef = useRef(null);
  const inputRef = useRef(null);

  // Import Open WebUI LLM Service
  const [llmService] = useState(() => {
    try {
      const service = require('../services/llmService').default;
      return service;
    } catch (error) {
      console.error('Failed to load LLM service:', error);
      return null;
    }
  });

  // Initialize speech recognition
  useEffect(() => {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      recognitionRef.current = new SpeechRecognition();

      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = 'en-US';

      recognitionRef.current.onstart = () => {
        setIsListening(true);
        setCurrentTranscript('');
      };

      recognitionRef.current.onresult = (event) => {
        let interimTranscript = '';
        let finalTranscript = '';

        for (let i = event.resultIndex; i < event.results.length; i++) {
          const transcript = event.results[i][0].transcript;
          if (event.results[i].isFinal) {
            finalTranscript += transcript;
          } else {
            interimTranscript += transcript;
          }
        }

        setCurrentTranscript(finalTranscript || interimTranscript);

        if (finalTranscript) {
          setInputMessage(finalTranscript.trim());
          setIsListening(false);
        }
      };

      recognitionRef.current.onerror = (event) => {
        console.error('Speech recognition error:', event.error);
        setIsListening(false);
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
        setCurrentTranscript('');
      };
    }

    // Test Open WebUI connection
    initializeOpenWebUI();

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  // Auto-scroll to bottom of messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Focus input when chat opens
  useEffect(() => {
    if (isOpen && !isMinimized) {
      setTimeout(() => {
        inputRef.current?.focus();
      }, 100);
    }
  }, [isOpen, isMinimized]);

  // Initialize Open WebUI connection
  const initializeOpenWebUI = async () => {
    try {
      setConnectionStatus('connecting');
      setDebugInfo('Initializing Open WebUI connection...');

      if (!llmService) {
        setConnectionStatus('error');
        setDebugInfo('LLM Service not loaded');
        return;
      }

      // Check basic configuration
      const status = llmService.getConnectionStatus();
      setDebugInfo(`Base URL: ${status.baseUrl}\nHas API Key: ${status.hasApiKey}`);

      if (!status.hasApiKey) {
        setConnectionStatus('error');
        setDebugInfo('❌ No API key found.\n\nPlease add your Open WebUI API key to the .env file:\nREACT_APP_LLM_API_KEY=your_api_key_here');
        return;
      }

      // Test connection and get models
      setTypingIndicator('Fetching available models...');
      const isConnected = await llmService.testConnection();

      if (isConnected) {
        setConnectionStatus('connected');
        const modelInfo = await llmService.getModelInfo();
        setModelInfo(modelInfo);
        setDebugInfo(`✅ Connected successfully!\n\nSelected Model: ${modelInfo.selectedModel}\nAvailable Models: ${modelInfo.availableModels.length}`);
      } else {
        setConnectionStatus('error');
        setDebugInfo('❌ Connection failed.\n\nPlease check:\n• Your API key is correct\n• Open WebUI is running\n• Network connectivity');
      }

    } catch (error) {
      setConnectionStatus('error');
      setDebugInfo(`❌ Connection error: ${error.message}`);
      console.error('Open WebUI connection error:', error);
    } finally {
      setTypingIndicator('');
    }
  };

  // Process query using Open WebUI
  const processOpenWebUIQuery = async (query) => {
    try {
      setIsProcessing(true);
      setTypingIndicator('Analyzing your query...');

      if (!llmService) {
        throw new Error('LLM Service not available');
      }

      if (connectionStatus !== 'connected') {
        throw new Error('Not connected to Open WebUI');
      }

      // Get conversation history for context
      const conversationHistory = messages
        .slice(-6)
        .filter(m => m.type === 'user' || m.type === 'ai')
        .map(m => ({
          role: m.type === 'user' ? 'user' : 'assistant',
          content: m.content
        }));

      setTypingIndicator('Processing with Open WebUI...');

      // Send query to Open WebUI
      const result = await llmService.sendQuery(query, data, conversationHistory);

      if (result.success) {
        // Determine navigation action
        let action = null;
        const lowerResponse = result.response.toLowerCase();
        const lowerQuery = query.toLowerCase();

        if ((lowerQuery.includes('student') || lowerResponse.includes('student')) && 
            (lowerResponse.includes('view') || lowerResponse.includes('check') || lowerResponse.includes('show'))) {
          action = { type: 'highlight', tab: 'students' };
        } else if ((lowerQuery.includes('teacher') || lowerResponse.includes('teacher')) && 
                   (lowerResponse.includes('view') || lowerResponse.includes('check') || lowerResponse.includes('show'))) {
          action = { type: 'highlight', tab: 'teachers' };
        } else if ((lowerQuery.includes('finance') || lowerResponse.includes('finance') || lowerQuery.includes('fee')) && 
                   (lowerResponse.includes('view') || lowerResponse.includes('check') || lowerResponse.includes('show'))) {
          action = { type: 'highlight', tab: 'finance' };
        } else if ((lowerQuery.includes('inventory') || lowerResponse.includes('inventory')) && 
                   (lowerResponse.includes('view') || lowerResponse.includes('check') || lowerResponse.includes('show'))) {
          action = { type: 'highlight', tab: 'inventory' };
        } else if ((lowerQuery.includes('analytics') || lowerResponse.includes('report') || lowerResponse.includes('analysis')) && 
                   (lowerResponse.includes('view') || lowerResponse.includes('check') || lowerResponse.includes('show'))) {
          action = { type: 'highlight', tab: 'analytics' };
        }

        // Add AI response to chat
        setMessages(prev => [...prev, {
          id: Date.now(),
          type: 'ai',
          content: result.response,
          timestamp: new Date().toISOString(),
          action: action,
          suggestions: result.suggestions,
          usage: result.usage,
          model: result.model
        }]);

        // Execute navigation action if needed
        if (action && action.type === 'highlight' && action.tab) {
          setTimeout(() => {
            onTabChange(action.tab);
          }, 1000);
        }

        // Update debug info
        setDebugInfo(`✅ Query successful!\n\nModel: ${result.model}\nTokens: ${result.usage?.total_tokens || 'N/A'}`);

      } else {
        // Use fallback response
        setMessages(prev => [...prev, {
          id: Date.now(),
          type: 'ai',
          content: result.fallbackResponse || result.error,
          timestamp: new Date().toISOString()
        }]);

        setDebugInfo(`❌ Query failed: ${result.error}`);
      }

    } catch (error) {
      console.error('Open WebUI query failed:', error);

      // Generate fallback response
      const fallbackResponse = generateFallbackResponse(query);
      setMessages(prev => [...prev, {
        id: Date.now(),
        type: 'ai',
        content: fallbackResponse,
        timestamp: new Date().toISOString()
      }]);

      setDebugInfo(`❌ Error: ${error.message}`);
    } finally {
      setIsProcessing(false);
      setTypingIndicator('');
    }
  };

  // Generate fallback response when Open WebUI is unavailable
  const generateFallbackResponse = (query) => {
    const lowerQuery = query.toLowerCase();

    if (lowerQuery.includes('student')) {
      const pendingFees = data.students.filter(s => s.fees.pending > 0).length;
      const avgAttendance = (data.students.reduce((sum, s) => sum + s.attendance.percentage, 0) / data.students.length).toFixed(1);
      return `📚 **Student Information** (Offline Mode)\n\n• **Total Students:** ${data.students.length}\n• **Average Attendance:** ${avgAttendance}%\n• **Students with Pending Fees:** ${pendingFees}\n\n*Open WebUI temporarily unavailable. For detailed information, please check the Students section.*`;
    }

    if (lowerQuery.includes('teacher')) {
      const avgExperience = (data.teachers.reduce((sum, t) => sum + t.experience, 0) / data.teachers.length).toFixed(1);
      return `👨‍🏫 **Teacher Information** (Offline Mode)\n\n• **Total Teachers:** ${data.teachers.length}\n• **Average Experience:** ${avgExperience} years\n• **Subjects:** ${[...new Set(data.teachers.map(t => t.subject))].join(', ')}\n\n*Open WebUI temporarily unavailable. For detailed information, please check the Teachers section.*`;
    }

    if (lowerQuery.includes('finance')) {
      const profitMargin = ((data.finance.netProfit / data.finance.totalRevenue) * 100).toFixed(1);
      return `💰 **Financial Information** (Offline Mode)\n\n• **Total Revenue:** ₹${data.finance.totalRevenue.toLocaleString()}\n• **Net Profit:** ₹${data.finance.netProfit.toLocaleString()}\n• **Profit Margin:** ${profitMargin}%\n• **Pending Fees:** ₹${data.finance.pendingFees.toLocaleString()}\n\n*Open WebUI temporarily unavailable. For detailed information, please check the Finance section.*`;
    }

    if (lowerQuery.includes('inventory')) {
      const lowStock = data.inventory.filter(item => item.quantity < item.minStock).length;
      const totalValue = data.inventory.reduce((sum, item) => sum + item.totalValue, 0);
      return `📦 **Inventory Information** (Offline Mode)\n\n• **Total Items:** ${data.inventory.length}\n• **Low Stock Items:** ${lowStock}\n• **Total Value:** ₹${totalValue.toLocaleString()}\n\n*Open WebUI temporarily unavailable. For detailed information, please check the Inventory section.*`;
    }

    return `I'm having trouble connecting to Open WebUI right now. Please try:\n\n• **Checking your API key configuration**\n• **Ensuring Open WebUI is running**\n• **Refreshing the page**\n• **Using the navigation menu** to browse sections\n\nWhat specific information about ${data.school.name} are you looking for?`;
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim()) return;

    // Add user message to chat
    setMessages(prev => [...prev, {
      id: Date.now(),
      type: 'user',
      content: inputMessage,
      timestamp: new Date().toISOString()
    }]);

    const query = inputMessage;
    setInputMessage('');

    // Process the query
    if (connectionStatus === 'connected') {
      await processOpenWebUIQuery(query);
    } else {
      // Use fallback response
      const fallbackResponse = generateFallbackResponse(query);
      setMessages(prev => [...prev, {
        id: Date.now(),
        type: 'ai',
        content: fallbackResponse,
        timestamp: new Date().toISOString()
      }]);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const startVoiceInput = () => {
    if (recognitionRef.current) {
      recognitionRef.current.start();
    }
  };

  const stopVoiceInput = () => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
    }
  };

  const getConnectionStatusColor = () => {
    switch (connectionStatus) {
      case 'connected': return 'text-green-500';
      case 'connecting': return 'text-yellow-500';
      case 'error': return 'text-red-500';
      default: return 'text-gray-500';
    }
  };

  const getConnectionStatusText = () => {
    switch (connectionStatus) {
      case 'connected': return modelInfo ? `${modelInfo.selectedModel.split('/').pop()}` : 'Connected';
      case 'connecting': return 'Connecting...';
      case 'error': return 'Disconnected';
      default: return 'Unknown';
    }
  };

  if (!isOpen) {
    return (
      <button
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 w-14 h-14 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-full shadow-lg hover:shadow-xl transition-all duration-300 flex items-center justify-center z-50 hover:scale-110"
      >
        <div className="relative">
          <Brain className="w-7 h-7" />
          <div className={`absolute -top-1 -right-1 w-3 h-3 rounded-full border-2 border-white ${
            connectionStatus === 'connected' ? 'bg-green-500 animate-pulse' : 
            connectionStatus === 'connecting' ? 'bg-yellow-500 animate-spin' : 
            'bg-red-500'
          }`}></div>
        </div>
      </button>
    );
  }

  return (
    <div className={`fixed bottom-6 right-6 bg-white rounded-lg shadow-2xl border z-50 transition-all duration-300 ${
      isMinimized ? 'w-80 h-16' : 'w-96 h-[600px]'
    }`}>
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white p-4 rounded-t-lg">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Brain className="w-5 h-5" />
            <h3 className="font-semibold">AI Assistant</h3>
            <div className="flex items-center space-x-1">
              {connectionStatus === 'connecting' ? (
                <Loader className="w-4 h-4 animate-spin" />
              ) : (
                <Zap className={`w-4 h-4 ${getConnectionStatusColor()}`} />
              )}
              <span className={`text-xs ${getConnectionStatusColor()}`}>
                {getConnectionStatusText()}
              </span>
            </div>
          </div>
          <div className="flex items-center space-x-2">
            {/* Debug Toggle */}
            {process.env.REACT_APP_DEBUG_MODE === 'true' && (
              <button
                onClick={() => setShowDebug(!showDebug)}
                className="p-1 hover:bg-white/20 rounded transition-colors"
                title="Toggle Debug Info"
              >
                <Settings className="w-4 h-4" />
              </button>
            )}
            <button
              onClick={() => setIsMinimized(!isMinimized)}
              className="p-1 hover:bg-white/20 rounded transition-colors"
            >
              {isMinimized ? <Maximize2 className="w-4 h-4" /> : <Minimize2 className="w-4 h-4" />}
            </button>
            <button
              onClick={() => setIsOpen(false)}
              className="p-1 hover:bg-white/20 rounded transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {!isMinimized && (
        <>
          {/* Debug Panel */}
          {showDebug && (
            <div className="bg-gray-100 p-3 border-b">
              <div className="text-xs text-gray-600 mb-2 flex items-center gap-2">
                <Info className="w-3 h-3" />
                Open WebUI Debug Info:
              </div>
              <div className="text-xs bg-white p-2 rounded border font-mono whitespace-pre-wrap max-h-24 overflow-y-auto">
                {debugInfo || 'No debug information available'}
              </div>
              <div className="flex gap-2 mt-2">
                <button
                  onClick={initializeOpenWebUI}
                  className="text-xs bg-blue-500 text-white px-2 py-1 rounded hover:bg-blue-600 transition-colors"
                  disabled={connectionStatus === 'connecting'}
                >
                  <RefreshCw className="w-3 h-3 inline mr-1" />
                  Reconnect
                </button>
                <button
                  onClick={() => llmService?.clearCache()}
                  className="text-xs bg-gray-500 text-white px-2 py-1 rounded hover:bg-gray-600 transition-colors"
                >
                  Clear Cache
                </button>
                {modelInfo && (
                  <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded">
                    {modelInfo.availableModels.length} models
                  </span>
                )}
              </div>
            </div>
          )}

          {/* Messages */}
          <div className={`flex-1 overflow-y-auto p-4 space-y-3 ${showDebug ? 'h-[350px]' : 'h-[450px]'}`}>
            {messages.map(message => (
              <div
                key={message.id}
                className={`flex ${message.type === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] px-4 py-3 rounded-lg ${
                    message.type === 'user'
                      ? 'bg-blue-600 text-white'
                      : 'bg-gray-100 text-gray-900'
                  }`}
                >
                  <div className="text-sm whitespace-pre-wrap leading-relaxed">{message.content}</div>
                  <div className="text-xs opacity-75 mt-2 flex items-center justify-between">
                    <span>{new Date(message.timestamp).toLocaleTimeString()}</span>
                    {message.usage && (
                      <span className="text-xs">
                        {message.model && `${message.model.split('/').pop()} • `}
                        {message.usage.total_tokens} tokens
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}

            {isProcessing && (
              <div className="flex justify-start">
                <div className="bg-gray-100 text-gray-900 px-4 py-3 rounded-lg">
                  <div className="flex items-center space-x-3">
                    <div className="flex space-x-1">
                      <div className="w-2 h-2 bg-blue-600 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-blue-600 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></div>
                      <div className="w-2 h-2 bg-blue-600 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                    </div>
                    <span className="text-sm">{typingIndicator}</span>
                  </div>
                </div>
              </div>
            )}

            {isListening && (
              <div className="flex justify-start">
                <div className="bg-blue-50 text-blue-800 px-4 py-3 rounded-lg border border-blue-200">
                  <div className="flex items-center space-x-2">
                    <Volume2 className="w-4 h-4 animate-pulse" />
                    <span className="text-sm">Listening... Speak clearly</span>
                  </div>
                  {currentTranscript && (
                    <div className="text-sm text-blue-600 italic mt-1">"{currentTranscript}"</div>
                  )}
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-4 border-t border-gray-200">
            <div className="flex space-x-2">
              <input
                ref={inputRef}
                type="text"
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder="Ask me anything about your school..."
                className="flex-1 border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                disabled={isProcessing}
              />

              {/* Voice Input Button */}
              <button
                onClick={isListening ? stopVoiceInput : startVoiceInput}
                disabled={isProcessing}
                className={`p-2 rounded-lg transition-colors ${
                  isListening 
                    ? 'bg-red-500 text-white animate-pulse' 
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                } disabled:opacity-50 disabled:cursor-not-allowed`}
                title={isListening ? 'Stop recording' : 'Start voice input'}
              >
                {isListening ? <Square className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
              </button>

              {/* Send Button */}
              <button
                onClick={handleSendMessage}
                disabled={isProcessing || !inputMessage.trim()}
                className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                title="Send message"
              >
                <Send className="w-5 h-5" />
              </button>
            </div>

            {/* Dynamic Suggestions */}
            <div className="mt-3 flex flex-wrap gap-2">
              {/* Show suggestions from the last AI response if available */}
              {messages.length > 0 && messages[messages.length - 1]?.suggestions ? 
                messages[messages.length - 1].suggestions.map((suggestion, index) => (
                  <button
                    key={index}
                    onClick={() => {
                      setInputMessage(suggestion);
                      setTimeout(() => handleSendMessage(), 100);
                    }}
                    className="text-xs bg-blue-100 text-blue-600 px-2 py-1 rounded-full hover:bg-blue-200 transition-colors"
                    disabled={isProcessing}
                  >
                    {suggestion}
                  </button>
                )) :
                // Default suggestions for Open WebUI
                [
                  "Show me student overview",
                  "Financial performance summary",
                  "Teacher performance report",
                  "What insights can you provide?"
                ].map((suggestion, index) => (
                  <button
                    key={index}
                    onClick={() => {
                      setInputMessage(suggestion);
                      setTimeout(() => handleSendMessage(), 100);
                    }}
                    className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-full hover:bg-gray-200 transition-colors"
                    disabled={isProcessing}
                  >
                    {suggestion}
                  </button>
                ))
              }
            </div>

            {/* Status */}
            <div className="mt-2 text-xs text-gray-500 text-center">
              {isProcessing ? (
                <div className="flex items-center justify-center space-x-1">
                  <div className="w-3 h-3 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                  <span>Processing with Open WebUI...</span>
                </div>
              ) : connectionStatus === 'connected' ? (
                <div className="flex items-center justify-center space-x-1">
                  <CheckCircle className="w-3 h-3 text-green-500" />
                  <span>Open WebUI connected • Press Enter to send</span>
                </div>
              ) : (
                <div className="flex items-center justify-center space-x-1">
                  <AlertCircle className="w-3 h-3 text-red-500" />
                  <span>Open WebUI offline • Using fallback mode</span>
                </div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default ChatAssistant;
